    private function decide($type,$id,$action,$r){return $this->txn(function()use($type,$id,$action,$r){global $wpdb;$table=self::table($type==='expense'?'expenses':'requests');$row=$this->state_row($table,$id);if(!$row)self::reject('درخواست پیدا نشد.',404);$f=$this->fund((int)$row->fund_id);$this->project_access($f);$b=self::body($r);if((int)$row->version!==self::uid($b['version']??0))self::reject('درخواست تغییر کرده است؛ صفحه را تازه کنید.',409);if((int)$row->requested_by===get_current_user_id())self::reject('ثبت‌کننده نمی‌تواند درخواست خودش را تأیید کند.',403);if($action==='accountant' && current_user_can('paydar_edit_exec_own')&&!current_user_can('manage_options'))self::reject('مدیر پروژه نمی‌تواند مرحله مالی را تأیید کند.',403);if($action==='manager'){if(!(int)current_user_can('paydar_edit_exec_own')||current_user_can(Paydar_Accounting::READ))self::reject('فقط مدیر پروژه می‌تواند این مرحله را بررسی کند.',403);if($row->status!=='submitted')self::reject('درخواست در این مرحله نیست.',409);$status='manager_approved';$field='manager_by';}elseif($action==='accountant'){if(!current_user_can(self::REVIEW)||(current_user_can('paydar_edit_exec_own')&&!current_user_can('manage_options')))self::reject('دسترسی حسابدار لازم است.',403);$allowed=$type==='expense'?'manager_approved':'manager_approved';if($row->status!==$allowed)self::reject('درخواست هنوز تأیید مدیر پروژه ندارد.',409);$field='accountant_by';$status='accountant_approved';}elseif($action==='senior'){if(!current_user_can(self::SENIOR)||(current_user_can(self::PAY)&&!current_user_can('manage_options')))self::reject('دسترسی مدیر ارشد لازم است.',403);if($row->status!=='accountant_approved')self::reject('درخواست در انتظار تأیید مدیر ارشد نیست.',409);$settings=$wpdb->get_row('SELECT approval_threshold FROM '.self::table('settings').' WHERE id=1');if(!$settings||(int)$row->amount<(int)$settings->approval_threshold||!(int)$settings->approval_threshold)self::reject('این درخواست به تأیید مدیر ارشد نیاز ندارد.',409);$field='s