    public function manager_request($r){return $this->decide('request',self::id($r),'manager',$r);}public function accountant_request($r){return $this->decide('request',self::id($r),'accountant',$r);}public function senior_request($r){return $this->decide('request',self::id($r),'senior',$r);}public function manager_expense($r){return $this->decide('expense',self::id($r),'manager',$r);}public function accountant_expense($r){return $this->decide('expense',self::id($r),'accountant',$r);}public function senior_expense($r){return $this->decide('expense',self::id($r),'senior',$r);}
    private function reject_item($table,$type,$r){return $this->txn(function()use($table,$type,$r){global $wpdb;$id=self::id($r);$row=$this->state_row(self::table($table),$id);if(!$row)self::reject('درخواست پیدا نشد.',404);$this->project_access($this->fund((int)$row->fund_id));$b=self::body($r);$reason=self::raw($b['reason']??'',1000);if(!$reason)self::reject('علت رد الزامی است.');if((int)$row->requested_by===get_current_user_id())self::reject('ثبت‌کننده نمی‌تواند درخواست خودش را رد کند.',403);if(!in_array($row->status,array('submitted','manager_approved','accountant_approved'),true))self::reject('درخواست در این مرحله قابل رد نیست.',409);if($table==='requests'&&!current_user_can(self::PAY)&&!current_user_can(self::SENIOR))self::reject('دسترسی رد درخواست ندارید.',403);if($table==='expenses'&&!current_user_can(self::REVIEW)&&!current_user_can(self::SENIOR))self::reject('دسترسی رد درخواست ندارید.',403);$this->audit($type,$id,'rejected',array('reason'=>$reason));self::must($wpdb->update(self::table($table),array('status'=>'rejected','version'=>(int)$row->version+1,'updated_at'=>current_time('mysql')),array('id'=>$id,'version'=>$row->version)));return array($type=>$this->state_row(self::table($table),$id));});}
    public function reject_request($r){return $this->reject_item('requests','request',$r);}public function reject_expense($r){return $this->reject_item('expenses','expense',$r);}
    private function reserve_post($table,$id,$version,$allowed,$type,$extra=array()){global $wpdb;return $this->txn(function()use($table,$id,$version,$allowed,$type,$extra){global $wpdb;$row=$this->state_row(self::table($table),$id);if(!$row)self::reject('درخواست پیدا نشد.',404);$this->allowed_fund($this->fund((int)$row->fund_id));if((int)$row->version!==(int)$version)self::reject('درخواست تغییر کرده است؛ صفحه را تازه کنید.',409);if(!in_array($row->status,$allowed,true))self::reject('درخواست در مرحله ثبت مالی یا تلاش مجدد نیست.',409);$this->audit($type,$id,'posting_started',array('from'=>$row->status));self::must($wpdb->update(self::table($table),array_merge($extra,array('status'=>'posting','version'=>(int)$row->version+1,'updated_at'=>current_time('mysql'))),array('id'=>$id,'version'=>$row->version)));return array('record'=>$this->state_row(self::table($table),$id));});}
