    public function pay_request($r){global $wpdb;$id=self::id($r);$b=self::body($r);$row=$this->state_row(self::table('requests'),$id);if(!$row)return self::err('درخواست پیدا نشد.',404);$f=$this->fund((int)$row->fund_id);$this->allowed_fund($f);if((int)$row->requested_by===get_current_user_id())return self::err('ثبت‌کننده درخواست نمی‌تواند پرداخت آن را ثبت کند.',403);try{$date=self::date($b['transfer_date']??'');$aid=self::uid($b['source_account_id']??0);if(in_array($row->status,array('posting','posting_error'),true)&&($row->transfer_date!==$date||(int)$row->source_account_id!==$aid||$row->transfer_ref!==self::raw($b['transfer_ref']??'',190)))self::reject('ثبت انتقال قبلاً آغاز شده؛ مشخصات اولیه را بدون تغییر دوباره بفرستید.',409);$this->validate_account($aid,'asset');$ref=self::raw($b['transfer_ref']??'',190);if($aid===(int)$f->cash_account_id)self::reject('حساب مبدأ و مقصد شارژ باید متفاوت باشند.');if(!$ref)self::reject('شماره رسید یا پیگیری انتقال لازم است.');$cfg=$wpdb->get_row('SELECT approval_threshold FROM '.self::table('settings').' WHERE id=1');if($cfg&&(int)$row->amount>=(int)$cfg->approval_threshold&&(int)$cfg->approval_threshold&&$row->status==='accountant_approved')self::reject('تأیید مدیر ارشد لازم است.',409);}catch(Throwable $e){return self::err($e->getMessage(),$e->getCode()?:400);}$reserved=$this->reserve_post('requests',$id,$b['version']??0,array('accountant_approved','senior_approved','posting_error','posting'),'request',array('source_account_id'=>$aid,'transfer_date'=>$date,'transfer_ref'=>$ref,'paid_by'=>get_current_user_id()));if(is_wp_error($reserved))return $reserved;$row=$reserved instanceof WP_REST_Response?$reserved->data['record']:$reserved['record'];$res=Paydar_Accounting::boot()->post_generated_entry('pc-replenishment-event-'.$id,$date,'شارژ تنخواه '.$f->name.' — '.$row->purpose,'petty_cash_replenishment',(string)$id,array(array('account_id'=>(int)$f->cash_account_id,'project_id'=>$f->project_id,'description'=>'شارژ تنخواه','debit'=>(st