    public function post_expense($r){global $wpdb;$id=self::id($r);$row=$this->state_row(self::table('expenses'),$id);if(!$row)return self::err('هزینه پیدا نشد.',404);$f=$this->fund((int)$row->fund_id);$this->allowed_fund($f);$cfg=$wpdb->get_row('SELECT approval_threshold FROM '.self::table('settings').' WHERE id=1');if($cfg&&(int)$row->amount>=(int)$cfg->approval_threshold&&(int)$cfg->approval_threshold&&$row->status==='accountant_approved')return self::err('تأیید مدیر ارشد لازم است.',409);$body=self::body($r);$reserved=$this->reserve_post('expenses',$id,$body['version']??0,array('accountant_approved','senior_approved','posting_error','posting'),'expense');if(is_wp_error($reserved))return $reserved;$row=$reserved instanceof WP_REST_Response?$reserved->data['record']:$reserved['record'];$cat=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('categories').' WHERE id=%d',$row->category_id));if(!$cat){$this->mark_post_error('expenses',$id,'دسته هزینه پیدا نشد.');return self::err('دسته هزینه پیدا نشد.',409);}$res=Paydar_Accounting::boot()->post_generated_entry($row->posting_key,$row->expense_date,'هزینه تنخواه '.$f->name.' — '.$row->description,'petty_cash_expense',(string)$id,array(array('account_id'=>(int)$cat->expense_account_id,'project_id'=>$f->project_id,'description'=>$row->description,'debit'=>(string)$row->amount,'credit'=>'0'),array('account_id'=>(int)$f->cash_account_id,'project_id'=>$f->project_id,'description'=>'پرداخت تنخواه','debit'=>'0','credit'=>(string)$row->amount)));if(is_wp_error($res)){$this->mark_post_error('expenses',$id,$res->get_error_message());return $res;}return $this->finish_post('expenses',$id,$res['entry']->id);}
    private function detail($table,$id){global $wpdb;$r=$this->state_row(self::table($table),$id);if(!$r)self::reject('مورد پیدا نشد.',404);$f=$this->fund((int)$r->fund_id);$this->allowed_fund($f);$r->fund_name=$f->name;$r->project_id=$f->project_id;$r->project_name=$wpdb->get_var($wpdb->prepare('SELECT name FROM '.$wpdb->prefix.'paydar_projects WHERE project_id=%s',$f->project_id));if($table==='expenses'){$r->category=$wpdb->get_row($wpdb->prepare('SELECT c.*,a.code,a.name AS account_name FROM '.self::table('categories').' c JOIN '.Paydar_Accounting::table('accounts').' a ON a.id=c.expense_account_id WHERE c.id=%d',$r->category_id));}return $r;}
