    public function reconcile_list($r){global $wpdb;try{$f=$this->fund(self::uid($r->get_param('fund_id')??0));$this->allowed_fund($f);$rows=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table('reconciliations').' WHERE fund_id=%d ORDER BY as_of_date DESC,id DESC LIMIT 30',$f->id));return rest_ensure_response(array('reconciliations'=>$rows));}catch(Throwable $e){return self::err($e->getMessage(),$e->getCode()?:400);}}
    private function pending_spent($fund_id,$date){global $wpdb;$t=self::table('expenses');$sql=$wpdb->prepare("SELECT COALESCE(SUM(x.amount),0) FROM $t x WHERE x.fund_id=%d AND x.expense_date<=%s AND x.status IN ('submitted','manager_approved','accountant_approved','senior_approved','posting','posting_error') AND (x.status<>'posting' OR NOT EXISTS (SELECT 1 FROM ".Paydar_Accounting::table('entries')." e WHERE e.status='posted' AND e.source_type='petty_cash_expense' AND e.source_id=CAST(x.id AS CHAR)))",$fund_id,$date);return (string)$wpdb->get_var($sql);}
    private function book_balance($f,$date){global $wpdb;$sql=$wpdb->prepare("SELECT COALESCE(SUM(l.debit-l.credit),0) FROM ".Paydar_Accounting::table('lines')." l JOIN ".Paydar_Accounting::table('entries')." e ON e.id=l.entry_id WHERE e.status='posted' AND l.account_id=%d AND e.entry_date<=%s",$f->cash_account_id,$date);return (string)$wpdb->get_var($sql);}
