    public function summary($r){global $wpdb;try{$sql='SELECT f.*,p.name AS project_name FROM '.self::table('funds').' f JOIN '.$wpdb->prefix.'paydar_projects p ON p.project_id=f.project_id WHERE 1=1';if(!$all)$sql.=' AND f.active=1';if(!current_user_can(Paydar_Accounting::READ)&&!current_user_can('manage_options'))$sql.=$wpdb->prepare(' AND p.manager_user_id=%d',get_current_user_id());$funds=$wpdb->get_results($sql.' ORDER BY p.name,f.name');$out=array();$asof=self::date($r->get_param('to')?:current_time('Y-m-d'));foreach($funds as $f){$this->allowed_fund($f);$pending=(string)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(amount),0) FROM ".self::table('expenses')." WHERE fund_id=%d AND expense_date<=%s AND status IN ('submitted','manager_approved','accountant_approved','senior_approved','posting_error')",$f->id,$asof));$book=$this->book_balance($f,$asof);$out[]=array('fund_id'=>$f->id,'fund'=>$f->name,'project_id'=>$f->project_id,'project_name'=>$f->project_name,'custodian_user_id'=>$f->custodian_user_id,'limit_amount'=>(string)$f->limit_amount,'book_balance'=>$book,'pending_amount'=>$pending,'expected_cash'=>(string)((int)$book-(int)$pending),'unit'=>(string)$wpdb->get_var('SELECT unit FROM '.Paydar_Accounting::table('settings').' WHERE id=1'));}return rest_ensure_response(array('funds'=>$out));}catch(Throwable $e){return self::err($e->getMessage(),$e->getCode()?:400);}}
    public function audit_list($r){global $wpdb;$page=max(1,min(100000,(int)$r->get_param('page')));$t=self::table('audit');$where='1=1';if(!current_user_can(Paydar_Accounting::READ)&&!current_user_can('manage_options')){$uid=get_current_user_id();$ids=array();foreach(array('request'=>'requests','expense'=>'expenses','reconciliation'=>'reconciliations') as $kind=>$table)$ids[]=$wpdb->prepare("(object_type=%s AND object_id IN (SELECT z.id FROM ".self::table($table)." z JOIN ".self::table('funds')." f ON f.id=z.fund_id JOIN ".$wpdb->prefix."paydar_projects p ON p.project_id=f.project_id WHERE p.manager_user_id=%d))",$kind,$uid);$where='('.implode(' OR ',$ids).')';}return rest_ensure_response(array('events'=>$wpdb->get_results("SELECT id,actor_id,action,object_type,object_id,created_at FROM $t WHERE $where ORDER BY id DESC LIMIT 50 OFFSET ".(($page-1)*50)),'total'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $t WHERE $where"),'page'=>$page));}
